import random
class Bank:
    def __init__(self,n,b):
        self.name = n
        self.balance = b
        self.accountNo = int(random.random()*(10**10))
        self.pin = &quot;&quot;
    def Menu(self):
        print(&apos;&apos;&apos;
        Welcome to city bank
        press 1 : deposit money
        press 2 : Withdraw money
        press 3 : check balance
        press 4 : Generate ATM pin
        press 5 : Change Pin
        press 6 : Exit
        &apos;&apos;&apos;)
        choice = input(&quot;Enter your choice : &quot;)
        if(choice==&apos;1&apos;):
            self.depositMoney()
        elif(choice==&apos;2&apos;):
            self.withdrawMoney()
        elif(choice == &apos;3&apos;):
            self.checkBalance()
        elif(choice==&apos;4&apos;):
            self.generatePin()
        elif(choice==&apos;5&apos;):
            self.changePin()
        elif(choice==&apos;6&apos;):
            self._exit()
        else:
            print(&quot;Invalid choice&quot;)
            self.Menu()

    def checkBalance(self):
        p = input(&quot;Enter your pin : &quot;)
        if(p==self.pin):
            print(&quot;Your balance is :&quot;,self.balance)
            self.Menu()
        else:
            if(self.pin==&quot;&quot;):
                print(&quot;Pin is not generated&quot;)
                x = input(&quot;To generate pin press 4 : &quot;)
                if(x==&apos;4&apos;):
                    self.generatePin()
                else:
                    print(&quot;Invalid choice&quot;)
                    self.Menu()
            else:
                print(&quot;Pin is wrong try again : &quot;)
                self.Menu()

    def generatePin(self):
        p = input(&quot;Enter your new pin : &quot;)
        if(len(p)!=4):
            print(&quot;Pin length should be four : &quot;)
            print(&quot;Try again&quot;)
            self.generatePin()
        self.pin = p
        print(&quot;New pin generated successfully&quot;)
        self.Menu()

    def changePin(self):
        if(self.pin==&quot;&quot;):
            print(&quot;Pin is not generated : &quot;)
            self.generatePin()
            return 0
        n = input(&quot;Enter your old pin : &quot;)
        if(n==self.pin):
            x = input(&quot;Enter new pin : &quot;)
            if (len(x) != 4):
                print(&quot;Pin length should be four : &quot;)
                print(&quot;Try again&quot;)
                self.changePin()
            self.pin = x
        else:
            print(&quot;Pin is incorrect&quot;)
            self.changePin()
        self.Menu()

    def depositMoney(self):
        m = input(&quot;Enter your money : &quot;)
        self.balance = int(self.balance) + int(m)
        print(&quot;Your balance is&quot;,self.balance)
        self.Menu()

    def withdrawMoney(self):
        m = input(&quot;Enter amount : &quot;)
        if(self.balance&lt;int(m)):
            print(&quot;Insufficeint balance&quot;)
            print(&quot;Enter another amount&quot;)
            self.withdrawMoney()
        self.balance = int(self.balance) - int(m)
        print(&quot;Your balance is&quot;,self.balance)
        self.Menu()

    def _exit(self):
        print(&quot;Thank you for visiting out ATM&quot;)


